slowEngine:
({
  query(root, selector) { return this.queryAll(root, selector)[0] || null; },
  queryAll(root, selector) {
    const end = Date.now() + 160;
    while (Date.now() < end) {}
    window.slowQueries = (window.slowQueries || 0) + 1;
    return Array.from(root.querySelectorAll(selector));
  }
})

